BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', v.viz)
FROM (VALUES
  ('ap-server-q9', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><text x="170" y="20" text-anchor="middle" font-size="12" fill="#8892a4">ミラーリング（RAID1）</text><rect x="40" y="40" width="110" height="60" rx="6" fill="none" stroke="#3b82f6" stroke-width="1.5"/><text x="95" y="60" text-anchor="middle" font-size="11" fill="#e8eaf0">ディスクA</text><text x="95" y="82" text-anchor="middle" font-size="11" fill="#6ab08d">データ</text><rect x="190" y="40" width="110" height="60" rx="6" fill="none" stroke="#60a5fa" stroke-width="1.5"/><text x="245" y="60" text-anchor="middle" font-size="11" fill="#e8eaf0">ディスクB</text><text x="245" y="82" text-anchor="middle" font-size="11" fill="#6ab08d">データ</text><line x1="150" y1="70" x2="190" y2="70" stroke="#8892a4" stroke-width="1.5"/><text x="170" y="63" text-anchor="middle" font-size="11" fill="#8892a4">＝</text><text x="170" y="118" text-anchor="middle" font-size="10" fill="#8892a4">同じデータを2台に複製。実効容量は1台分</text></svg>'),
  ('ap-server-q10', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><text x="170" y="18" text-anchor="middle" font-size="12" fill="#8892a4">パリティ分散（RAID5・4台構成）</text><rect x="15" y="35" width="72" height="55" rx="5" fill="none" stroke="#3b82f6" stroke-width="1.2"/><text x="51" y="54" text-anchor="middle" font-size="10" fill="#e8eaf0">1</text><text x="51" y="72" text-anchor="middle" font-size="9" fill="#6ab08d">データ</text><rect x="97" y="35" width="72" height="55" rx="5" fill="none" stroke="#3b82f6" stroke-width="1.2"/><text x="133" y="54" text-anchor="middle" font-size="10" fill="#e8eaf0">2</text><text x="133" y="72" text-anchor="middle" font-size="9" fill="#6ab08d">データ</text><rect x="179" y="35" width="72" height="55" rx="5" fill="none" stroke="#3b82f6" stroke-width="1.2"/><text x="215" y="54" text-anchor="middle" font-size="10" fill="#e8eaf0">3</text><text x="215" y="72" text-anchor="middle" font-size="9" fill="#c9a04a">パリティ</text><rect x="261" y="35" width="72" height="55" rx="5" fill="none" stroke="#3b82f6" stroke-width="1.2"/><text x="297" y="54" text-anchor="middle" font-size="10" fill="#e8eaf0">4</text><text x="297" y="72" text-anchor="middle" font-size="9" fill="#6ab08d">データ</text><text x="170" y="112" text-anchor="middle" font-size="10" fill="#8892a4">パリティは1台分の欠損を残り3台から計算し直せる</text></svg>'),
  ('ap-server-q13', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><text x="170" y="18" text-anchor="middle" font-size="12" fill="#8892a4">同じ4台（250GB×4）での実効容量比較</text><text x="20" y="52" font-size="11" fill="#e8eaf0">RAID1</text><rect x="70" y="40" width="200" height="18" rx="3" fill="none" stroke="#2a2f3f"/><rect x="70" y="40" width="133" height="18" rx="3" fill="#60a5fa"/><text x="278" y="53" font-size="11" fill="#8892a4">500GB</text><text x="20" y="92" font-size="11" fill="#e8eaf0">RAID5</text><rect x="70" y="80" width="200" height="18" rx="3" fill="none" stroke="#2a2f3f"/><rect x="70" y="80" width="200" height="18" rx="3" fill="#6ab08d"/><text x="278" y="93" font-size="11" fill="#8892a4">750GB</text><text x="170" y="120" text-anchor="middle" font-size="10" fill="#8892a4">RAID1は2台分、RAID5は3台分が実際に使える</text></svg>'),
  ('ap-server-q20', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><text x="90" y="18" text-anchor="middle" font-size="11" fill="#8892a4">Active-Active</text><rect x="30" y="35" width="100" height="30" rx="5" fill="none" stroke="#6ab08d" stroke-width="1.3"/><text x="80" y="54" text-anchor="middle" font-size="10" fill="#6ab08d">稼働中</text><rect x="30" y="75" width="100" height="30" rx="5" fill="none" stroke="#6ab08d" stroke-width="1.3"/><text x="80" y="94" text-anchor="middle" font-size="10" fill="#6ab08d">稼働中</text><text x="250" y="18" text-anchor="middle" font-size="11" fill="#8892a4">Active-Standby</text><rect x="200" y="35" width="100" height="30" rx="5" fill="none" stroke="#6ab08d" stroke-width="1.3"/><text x="250" y="54" text-anchor="middle" font-size="10" fill="#6ab08d">稼働中</text><rect x="200" y="75" width="100" height="30" rx="5" fill="none" stroke="#8892a4" stroke-width="1.3" stroke-dasharray="3,2"/><text x="250" y="94" text-anchor="middle" font-size="10" fill="#8892a4">待機中</text><text x="170" y="122" text-anchor="middle" font-size="10" fill="#8892a4">Active-Activeは全台が普段から処理を分担する</text></svg>'),
  ('ap-server-q29', '<svg viewBox="0 0 340 140" xmlns="http://www.w3.org/2000/svg"><text x="170" y="18" text-anchor="middle" font-size="12" fill="#8892a4">公開鍵暗号方式の流れ</text><rect x="10" y="45" width="70" height="34" rx="5" fill="none" stroke="#2a2f3f"/><text x="45" y="66" text-anchor="middle" font-size="10" fill="#e8eaf0">平文</text><text x="95" y="66" text-anchor="middle" font-size="10" fill="#3b82f6">公開鍵で暗号化</text><rect x="150" y="45" width="70" height="34" rx="5" fill="none" stroke="#2a2f3f"/><text x="185" y="66" text-anchor="middle" font-size="10" fill="#c9a04a">暗号文</text><text x="255" y="66" text-anchor="middle" font-size="10" fill="#60a5fa">秘密鍵で復号</text><rect x="270" y="45" width="60" height="34" rx="5" fill="none" stroke="#2a2f3f"/><text x="300" y="66" text-anchor="middle" font-size="10" fill="#e8eaf0">平文</text><text x="170" y="112" text-anchor="middle" font-size="10" fill="#8892a4">公開鍵は誰に渡してよいが、秘密鍵は本人だけが持つ</text></svg>'),
  ('ap-server-q36', '<svg viewBox="0 0 340 150" xmlns="http://www.w3.org/2000/svg"><text x="90" y="16" text-anchor="middle" font-size="11" fill="#8892a4">正規化前</text><rect x="20" y="28" width="140" height="60" rx="5" fill="none" stroke="#c47070" stroke-width="1.2"/><text x="90" y="46" text-anchor="middle" font-size="9" fill="#e8eaf0">注文（商品名・単価を毎回コピー）</text><text x="90" y="62" text-anchor="middle" font-size="9" fill="#c47070">りんご 100円</text><text x="90" y="76" text-anchor="middle" font-size="9" fill="#c47070">りんご 100円</text><text x="250" y="16" text-anchor="middle" font-size="11" fill="#8892a4">正規化後</text><rect x="190" y="28" width="60" height="55" rx="5" fill="none" stroke="#6ab08d" stroke-width="1.2"/><text x="220" y="48" text-anchor="middle" font-size="9" fill="#e8eaf0">注文</text><text x="220" y="64" text-anchor="middle" font-size="9" fill="#6ab08d">商品ID</text><rect x="265" y="28" width="60" height="55" rx="5" fill="none" stroke="#6ab08d" stroke-width="1.2"/><text x="295" y="48" text-anchor="middle" font-size="9" fill="#e8eaf0">商品</text><text x="295" y="64" text-anchor="middle" font-size="9" fill="#6ab08d">名前/単価</text><line x1="250" y1="55" x2="265" y2="55" stroke="#6ab08d" stroke-width="1.2"/><text x="170" y="122" text-anchor="middle" font-size="10" fill="#8892a4">商品情報を切り出せば、単価変更は1か所で済む</text></svg>')
) AS v(source_ref, viz)
WHERE q.source_ref = v.source_ref
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'ap-server')
  AND q.explanation_data IS NOT NULL;

COMMIT;
